"""Listing guidance and final-copy examples with native tool selection preserved."""

from pydantic import JsonValue

from experimental.curator.harness.preparation import PreparationRequest
from experimental.curator.harness.resources import (
    CapabilityContribution,
    CapabilityRegistrar,
    CapabilitySelection,
    RegistrationReceipt,
    SelectionRequest,
    SkillContribution,
    SkillSelection,
)
from experimental.curator.harness.state import Task
from experimental.curator.harness.strategies import CapabilityStrategy


LISTING_GUIDANCE = """Listing 工作方法（以当次材料为准）：
1. 按本次路径和适用版本读取工作规则、SKU 参数、认证记录及准许写法、拼写表、单位换算表和营销草稿；路径不明时用现有查找能力定位。完整读取必要部分，分页或截断时补齐；已经完整且未变更的内容直接复用，不重复读取。规则冲突未解决时不猜定。
2. 从当次材料确定长度及计数口径、单位及舍入精度、拼写、认证筛选及准许表述、交付边界；新卖家或新材料不沿用旧值。SKU 数据和认证记录支撑事实，营销草稿不是证明。保留有依据的卖点，删去或收窄无依据的表述，不扩大或缩减卖家规定的核对条件。
3. 先按 listing-final-copy 第四节把有计算依据的容量双单位填入候选；按第三节组装本次词数的纯大写英文单词主题短语、本次分隔符及完整正文，按第二节保留每处参数限定。候选只含本次允许的标题和五条要点，不写完成报告；正文已在上下文，无需再读 Skill，不新增核对表或中间文件。
4. 对最后修改后的同一份候选核对事实、必需参数、长度、拼写、单位和格式；将其中容量数值逐一对照实际计算结果，不能以小数位数或字符计数代替数值核验。按第一节直接沿用修正后的成稿作为最终回复，从当次完整标题段名开始到第五条结束，不再根据核对结论重新写一篇回答。
5. 普通质量问题先修正文案，当轮交付有依据的英文成稿。局部材料缺失或读取失败不造数、不宣称未经执行的核验已通过；保留可确认内容，必要缺口仅放在本次格式允许的位置，不混入营销文案。缺口使所需交付根本无法成立时才简短请求具体补充，不能以计划或进度承诺替代已有可交付内容。"""

SKILL_NAME = "listing-final-copy"
SKILL_SOURCE = "curator-capability"
SKILL_ASSET = "assets/listing-final-copy/SKILL.md"


class ListingCapability(CapabilityStrategy):
    """Supply stable methodology without storing seller facts or task progress."""

    def __init__(self, registrar: CapabilityRegistrar) -> None:
        self._registrar = registrar

    def register(self, contribution: CapabilityContribution) -> RegistrationReceipt:
        return self._registrar.register(contribution)

    def _prepare_skills(self, request: PreparationRequest) -> tuple[SkillContribution, ...]:
        return (
            SkillContribution(
                name=SKILL_NAME,
                owner="capability",
                package=None,
                files={"SKILL.md": request.assets[SKILL_ASSET]},
                source="listing-final-copy:assembly-R1-R4-v4",
            ),
        )

    async def select(self, request: SelectionRequest) -> CapabilitySelection:
        seen: set[tuple[str, str]] = set()
        selected: list[SkillSelection] = []
        required_available = False
        for skill in request.skills:
            identity = (skill.source, skill.name)
            if identity in seen:
                raise ValueError(f"duplicate skill identity: {skill.source}/{skill.name}")
            seen.add(identity)
            is_required = identity == (SKILL_SOURCE, SKILL_NAME)
            if not skill.available:
                continue
            if is_required:
                required_available = True
            selected.append(
                SkillSelection(
                    name=skill.name,
                    source=skill.source,
                    delivery="body" if is_required else "catalog",
                )
            )
        if not required_available:
            raise ValueError(f"required skill missing or unavailable: {SKILL_SOURCE}/{SKILL_NAME}")
        return CapabilitySelection(tools=None, skills=tuple(selected), guidance=LISTING_GUIDANCE)


def create(
    state: dict[str, JsonValue],
    task: Task,
    *,
    registrar: CapabilityRegistrar,
) -> ListingCapability:
    """Bind the registrar without mutating the host task or session checkpoint."""
    return ListingCapability(registrar)
